const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, PageOrientation, LevelFormat,
  TabStopType, TabStopPosition, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageNumber, PageBreak, TableOfContents
} = require('docx');
const fs = require('fs');

// Brand colors
const BRAND_DARK = "1A1A1A";
const BRAND_GOLD = "B08D57";
const BRAND_LIGHT = "F5F1EA";
const BRAND_GRAY = "6B6B6B";
const BORDER_COLOR = "CCCCCC";

// Helper: border
const thinBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER_COLOR };
const cellBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

// Helper: standard paragraph
function p(text, opts = {}) {
  const runs = Array.isArray(text) ? text : [new TextRun({ text, ...opts.run })];
  return new Paragraph({
    children: runs,
    spacing: { after: 120, ...opts.spacing },
    alignment: opts.alignment,
    ...opts.paragraph
  });
}

// Helper: heading 1
function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 36 })],
    spacing: { before: 400, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  });
}

// Helper: heading 2
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 28 })],
    spacing: { before: 300, after: 160 }
  });
}

// Helper: heading 3
function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, color: BRAND_GOLD, size: 22, allCaps: true })],
    spacing: { before: 200, after: 100 }
  });
}

// Helper: bullet
function bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    children: [new TextRun({ text, size: 22 })],
    spacing: { after: 80 }
  });
}

// Helper: table cell
function tc(text, opts = {}) {
  return new TableCell({
    borders: cellBorders,
    width: { size: opts.width, type: WidthType.DXA },
    shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
    margins: { top: 100, bottom: 100, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({
        text: String(text),
        bold: opts.bold,
        color: opts.color || (opts.bold ? BRAND_DARK : "333333"),
        size: opts.size || 20
      })],
      alignment: opts.alignment
    })]
  });
}

// Helper: header row
function headerRow(cells, widths) {
  return new TableRow({
    tableHeader: true,
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: BRAND_DARK, bold: true, color: "FFFFFF", size: 20 }))
  });
}

// Helper: data row
function dataRow(cells, widths, fills = []) {
  return new TableRow({
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: fills[i] }))
  });
}

// Helper: divider paragraph
function divider() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    spacing: { before: 100, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 1 } }
  });
}

// Helper: spacer
function spacer(size = 200) {
  return new Paragraph({ children: [new TextRun({ text: "" })], spacing: { after: size } });
}

// ============================================================
// CONTENT
// ============================================================

const children = [];

// COVER PAGE
children.push(
  new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 2400 } }),
  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: BRAND_GOLD, size: 20, allCaps: true, characterSpacing: 40 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Market Blueprint", bold: true, color: BRAND_DARK, size: 72 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Revenue Diagnostic, Competitive Positioning, and Scaling Roadmap", color: BRAND_GRAY, size: 28, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "", color: BRAND_GOLD })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  }),
  new Paragraph({
    children: [new TextRun({ text: "PREPARED FOR", color: BRAND_GRAY, size: 18, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Marrow Aesthetics & Longevity", bold: true, color: BRAND_DARK, size: 32 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Two-Location Boutique Practice  |  Urban Market", color: BRAND_GRAY, size: 22 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "SAMPLE DELIVERABLE", bold: true, color: BRAND_GOLD, size: 18, allCaps: true, characterSpacing: 40 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Fictional practice profile, real deliverable structure", color: BRAND_GRAY, size: 18, italics: true })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({ children: [new PageBreak()] })
);

// ============================================================
// SECTION 1: EXECUTIVE SUMMARY
// ============================================================
children.push(h1("01  Executive Summary"));
children.push(p([
  new TextRun({ text: "Marrow Aesthetics & Longevity operates two boutique locations in a dense urban market, pairing core aesthetic services with a growing longevity and wellness vertical. Year-to-date revenue tracks at approximately ", size: 22 }),
  new TextRun({ text: "$712,000 combined", bold: true, size: 22 }),
  new TextRun({ text: ", with healthy operating margins and a loyal organic patient base. The practice is profitable, well-reviewed, and positioned above the volume-driven competitive set in its trade area.", size: 22 })
]));
children.push(p([
  new TextRun({ text: "However, three structural gaps are limiting the path from good to great.", size: 22 })
]));

children.push(h3("The Headline Finding"));
children.push(p([
  new TextRun({ text: "Marrow is leaving an estimated ", size: 22 }),
  new TextRun({ text: "$340,000 to $410,000 in annualized revenue on the table", bold: true, color: BRAND_GOLD, size: 22 }),
  new TextRun({ text: " across four recoverable categories, without adding a single new patient or a dollar of ad spend. The scaling conversation (location three, exit readiness, multi-unit margin) cannot begin until that foundation is sealed.", size: 22 })
]));

children.push(h3("Top-Line Benchmarks Versus Peer Set"));

const summaryTableWidths = [2800, 2200, 2200, 2200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: summaryTableWidths,
  rows: [
    headerRow(["Metric", "Marrow (YTD)", "Peer Median", "Top Quartile"], summaryTableWidths),
    dataRow(["Revenue per Provider / Mo", "$42,100", "$58,000", "$82,000"], summaryTableWidths, [null, "FFF4E5", null, null]),
    dataRow(["Revenue per Treatment Room / Mo", "$18,400", "$26,500", "$38,000"], summaryTableWidths, [null, "FFF4E5", null, null]),
    dataRow(["Consult-to-Treatment Conversion", "48%", "62%", "78%"], summaryTableWidths, [null, "FFF4E5", null, null]),
    dataRow(["Membership Penetration", "28%", "35%", "55%"], summaryTableWidths, [null, "FFF4E5", null, null]),
    dataRow(["12-Month Patient Retention", "41%", "56%", "72%"], summaryTableWidths, [null, "FFF4E5", null, null]),
    dataRow(["Average Patient LTV (24 mo)", "$2,180", "$3,400", "$5,900"], summaryTableWidths, [null, "FFF4E5", null, null]),
  ]
}));

children.push(spacer(160));
children.push(p([
  new TextRun({ text: "Interpretation: ", bold: true, size: 22 }),
  new TextRun({ text: "Marrow is operating at peer-median performance on surface metrics (revenue, reviews, referral volume) but trails the peer median materially on every internal-economics metric. This is the fingerprint of a practice that has built brand equity faster than it has built operational infrastructure. The upside is that every gap below is closeable without changing the brand.", size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 2: PRACTICE SNAPSHOT
// ============================================================
children.push(h1("02  Practice Snapshot"));

children.push(h2("Current-State Inputs"));

const snapshotWidths = [3200, 6200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: snapshotWidths,
  rows: [
    dataRow(["Locations", "2 (flagship + studio)"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Operating Model", "Physician-owned, boutique positioning, aesthetics + longevity"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Clinical Team", "1 MD (aesthetics co-owner), 1 MD (longevity), 1 RN injector"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Support Team", "3 front desk, 1 MA, 1 laser tech (shared across sites)"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Treatment Rooms", "6 combined (4 flagship, 2 studio)"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Primary Tech Stack", "Aesthetic Record (EMR), RepeatMD (membership), GHL (CRM), proprietary dashboard"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Marketing Posture", "Organic-dominant (SEO, Google Business, referral); no paid social"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["YTD Aesthetics Revenue", "$548,000"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["YTD Longevity Revenue", "$164,000"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Active Members", "215 (28% of active patient file)"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Monthly New Patients (avg)", "93"], snapshotWidths, [BRAND_LIGHT, null]),
    dataRow(["Monthly Leads (avg)", "230"], snapshotWidths, [BRAND_LIGHT, null]),
  ]
}));

children.push(spacer(200));

children.push(h2("Owner-Stated Goals"));
children.push(bullet("Understand what great looks like at this revenue tier, with defensible benchmarks."));
children.push(bullet("Identify the specific levers that move the practice from good to top-quartile."));
children.push(bullet("Establish the financial and operational pattern required to open location three within 18 to 24 months."));
children.push(bullet("Preserve boutique positioning; avoid volume-driven, discount-led competitive drift."));
children.push(bullet("Build a business that is scalable without the owner inside every transaction."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 3: COMPETITIVE LANDSCAPE
// ============================================================
children.push(h1("03  Competitive Landscape"));

children.push(p([
  new TextRun({ text: "The Luxora team mapped every aesthetic and wellness operator within a 3.5-mile radius of both Marrow locations, then narrowed to the six practices that pull from overlapping patient demographics. The analysis below profiles the top four direct competitors by positioning, offer architecture, digital presence, and observed ad behavior. Competitor names are redacted in this sample and presented as anonymized profiles.", size: 22 })
]));

children.push(h2("Direct Competitor Set"));

const compWidths = [1900, 1600, 1900, 1900, 2100];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: compWidths,
  rows: [
    headerRow(["Competitor", "Positioning", "Est. Monthly Revenue", "Monthly Ad Spend", "Signature Offer"], compWidths),
    dataRow(["Competitor A", "Volume / discount", "$180K-$220K", "$14,000 (Meta + Google)", "$8/unit Botox Tuesdays"], compWidths),
    dataRow(["Competitor B", "Celebrity-provider", "$95K-$115K", "$6,200 (Meta-heavy)", "Free consult + $500 off facial balancing"], compWidths),
    dataRow(["Competitor C", "Wellness-adjacent", "$70K-$85K", "$2,800 (Google only)", "Hormone optimization package $2,400"], compWidths),
    dataRow(["Competitor D", "Boutique / clinical", "$55K-$70K", "$0 observable", "Membership only, no promos"], compWidths),
    dataRow(["Marrow", "Boutique / physician-led", "~$89K/mo combined", "$0 observable", "Organic referral + membership"], compWidths, [BRAND_LIGHT, BRAND_LIGHT, BRAND_LIGHT, BRAND_LIGHT, BRAND_LIGHT]),
  ]
}));

children.push(spacer(200));

children.push(h2("Ad-Spend Intelligence"));
children.push(p([
  new TextRun({ text: "Meta Ad Library and Google Ads Transparency Center data pulled for the trailing 90 days shows the competitive set is spending an aggregate of approximately ", size: 22 }),
  new TextRun({ text: "$23,000 per month", bold: true, size: 22 }),
  new TextRun({ text: " on paid acquisition in this trade area. Marrow is spending zero. Three observations:", size: 22 })
]));
children.push(bullet("Competitor A's spend is concentrated on discount-led Botox and filler promotions. This is cannibalizing price in the market but not pulling high-LTV patients. Marrow's boutique positioning is insulated from this, which is good, but also means Marrow is not visible to the small segment of Competitor A's audience that would convert up-market."));
children.push(bullet("Competitor B is running polished Meta retargeting with physician-forward creative. This is the nearest positional threat to Marrow and is actively converting patients who search 'physician-led med spa' in the trade area."));
children.push(bullet("Competitor C is spending meaningfully on longevity and hormone search terms. Marrow's longevity vertical is currently invisible on paid channels and is forfeiting the category to a competitor with a weaker clinical story."));

children.push(h2("Positioning Matrix"));
children.push(p([
  new TextRun({ text: "Plotted on a two-axis map of ", italics: true, size: 22 }),
  new TextRun({ text: "clinical depth", italics: true, bold: true, size: 22 }),
  new TextRun({ text: " (x) against ", italics: true, size: 22 }),
  new TextRun({ text: "brand premium", italics: true, bold: true, size: 22 }),
  new TextRun({ text: ", Marrow currently occupies the upper-right quadrant alongside Competitor D. Competitor D is the practice Marrow is most directly benchmarked against for peer comparison, and Competitor B is the practice Marrow must out-position within the next 12 months to protect the boutique share.", size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 4: REVENUE LEAK AUDIT
// ============================================================
children.push(h1("04  Revenue Leak Audit"));
children.push(p([
  new TextRun({ text: "This section quantifies the revenue already inside Marrow's operation that is not being captured. Each leak is calculated conservatively using Marrow's own 12-month data, with peer-median and top-quartile recovery benchmarks for reference.", size: 22 })
]));

children.push(h2("Leak #1  Consult-to-Treatment Conversion Gap"));

const leak1Widths = [3200, 2100, 2100, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: leak1Widths,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], leak1Widths),
    dataRow(["Consult-to-Treatment Rate", "48%", "62%", "78%"], leak1Widths),
    dataRow(["Monthly Consults Booked", "142", "-", "-"], leak1Widths),
    dataRow(["Consults That Do Not Convert", "74", "-", "-"], leak1Widths),
    dataRow(["Avg First-Treatment Ticket", "$680", "-", "-"], leak1Widths),
    dataRow(["Monthly Revenue Forfeited (to peer median)", "$13,600", "-", "-"], leak1Widths, [null, "FFF4E5", null, null]),
    dataRow(["Annualized Revenue Forfeited", "$163,000", "-", "-"], leak1Widths, [BRAND_LIGHT, null, null, null]),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "Root cause: ", bold: true, size: 22 }),
  new TextRun({ text: "Consults are being delivered as clinical education rather than structured conversion conversations. No permission-based close, no assumptive booking, no same-day treatment pathway for qualified patients. This is a training and script issue, not a traffic issue.", size: 22 })
]));

children.push(h2("Leak #2  Membership Penetration Gap"));

const leak2Widths = [3200, 2100, 2100, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: leak2Widths,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], leak2Widths),
    dataRow(["Active Members", "215", "-", "-"], leak2Widths),
    dataRow(["Active Patient File", "768", "-", "-"], leak2Widths),
    dataRow(["Membership Penetration", "28%", "35%", "55%"], leak2Widths),
    dataRow(["Avg Membership MRR per Member", "$149", "-", "-"], leak2Widths),
    dataRow(["Monthly MRR Forfeited (to 55% top quartile)", "$30,200", "-", "-"], leak2Widths, [null, "FFF4E5", null, null]),
    dataRow(["Annualized MRR Forfeited", "$362,000", "-", "-"], leak2Widths, [BRAND_LIGHT, null, null, null]),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "Root cause: ", bold: true, size: 22 }),
  new TextRun({ text: "The membership is positioned as an optional loyalty product, not as the default onboarding pathway for every new patient. Top-quartile operators enroll members at the point of first treatment, not at the point of third or fourth visit. The product itself is sound; the enrollment choreography is not installed.", size: 22 })
]));

children.push(h2("Leak #3  Retention and Rebook Cadence"));

const leak3Widths = [3200, 2100, 2100, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: leak3Widths,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], leak3Widths),
    dataRow(["12-Month Patient Retention", "41%", "56%", "72%"], leak3Widths),
    dataRow(["% Patients Rebooked Before Leaving", "34%", "68%", "89%"], leak3Widths),
    dataRow(["Avg Visits per Patient per Year", "2.1", "3.4", "5.2"], leak3Widths),
    dataRow(["Lost Visit Revenue (peer median)", "$9,800/mo", "-", "-"], leak3Widths, [null, "FFF4E5", null, null]),
    dataRow(["Annualized Lost Visit Revenue", "$118,000", "-", "-"], leak3Widths, [BRAND_LIGHT, null, null, null]),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "Root cause: ", bold: true, size: 22 }),
  new TextRun({ text: "No structured pre-book-out-the-door protocol. Patients are leaving without their next appointment on the calendar and are being recaptured only if the AI follow-up reaches them before a competitor does. The dashboard flagged retention as healthy; the underlying cadence data tells a different story.", size: 22 })
]));

children.push(h2("Leak #4  Package Architecture and Upsell"));

const leak4Widths = [3200, 2100, 2100, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: leak4Widths,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], leak4Widths),
    dataRow(["Avg Ticket per Visit", "$412", "$520", "$780"], leak4Widths),
    dataRow(["% Visits With an Add-On", "18%", "42%", "67%"], leak4Widths),
    dataRow(["Active Package Sales / Month", "11", "28", "51"], leak4Widths),
    dataRow(["Avg Package Value", "$1,400", "$2,100", "$3,400"], leak4Widths),
    dataRow(["Annualized Upsell / Package Leak", "$94,000", "-", "-"], leak4Widths, [BRAND_LIGHT, null, null, null]),
  ]
}));

children.push(spacer(160));

children.push(h2("Total Recoverable Revenue"));

const totalWidths = [5400, 4000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: totalWidths,
  rows: [
    dataRow(["Leak #1 - Consult Conversion", "$163,000"], totalWidths),
    dataRow(["Leak #2 - Membership Penetration", "$362,000"], totalWidths),
    dataRow(["Leak #3 - Retention / Rebook", "$118,000"], totalWidths),
    dataRow(["Leak #4 - Package / Upsell", "$94,000"], totalWidths),
    new TableRow({
      children: [
        tc("ANNUALIZED RECOVERABLE TOTAL (unadjusted)", { width: 5400, bold: true, fill: BRAND_DARK, color: "FFFFFF", size: 22 }),
        tc("$737,000", { width: 4000, bold: true, fill: BRAND_DARK, color: BRAND_GOLD, size: 22 })
      ]
    }),
    new TableRow({
      children: [
        tc("Conservative capture estimate (45-55%)", { width: 5400, bold: true, fill: BRAND_LIGHT, size: 22 }),
        tc("$340,000 - $410,000", { width: 4000, bold: true, fill: BRAND_LIGHT, color: BRAND_GOLD, size: 22 })
      ]
    }),
  ]
}));

children.push(spacer(160));
children.push(p([
  new TextRun({ text: "The leaks are additive, not overlapping. Membership enrollment lifts consult conversion. Consult conversion lifts package sales. Package sales lift retention. Each fix compounds the next, which is why the conservative capture range of $340K to $410K is the number to plan around, not the gross $737K.", size: 22, italics: true })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 5: DIGITAL AND DEMAND ANALYSIS
// ============================================================
children.push(h1("05  Digital Presence & Demand Analysis"));

children.push(h2("Organic Channel Health"));
const digitalWidths = [3600, 2400, 1800, 1600];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: digitalWidths,
  rows: [
    headerRow(["Channel", "Marrow", "Peer Median", "Verdict"], digitalWidths),
    dataRow(["Google Business Profile Reviews", "412 (4.9)", "180 (4.7)", "Top quartile"], digitalWidths),
    dataRow(["Monthly GBP Profile Views", "9,400", "4,200", "Strong"], digitalWidths),
    dataRow(["Monthly Organic Website Sessions", "3,100", "2,800", "At median"], digitalWidths),
    dataRow(["Website Conversion Rate", "2.1%", "3.8%", "Under"], digitalWidths),
    dataRow(["Instagram Followers", "4,200", "6,100", "Under"], digitalWidths),
    dataRow(["IG Engagement Rate", "1.8%", "2.4%", "Under"], digitalWidths),
    dataRow(["Monthly Referral Patients", "38", "12", "Top quartile"], digitalWidths),
  ]
}));

children.push(spacer(160));
children.push(p([
  new TextRun({ text: "Read: ", bold: true, size: 22 }),
  new TextRun({ text: "Marrow owns its local search and reputation moat. The weak points are the website conversion surface (losing qualified organic traffic at the form) and the social layer (under-indexed against a market where visual proof drives consideration). These are fixable without a rebrand.", size: 22 })
]));

children.push(h2("Search Demand in Trade Area"));

const searchWidths = [4800, 2400, 2200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: searchWidths,
  rows: [
    headerRow(["Search Theme", "Monthly Volume", "Marrow Capture"], searchWidths),
    dataRow(["Botox / filler near me", "8,100", "~3% (SEO only)"], searchWidths),
    dataRow(["Facial balancing / natural results", "1,400", "~9%"], searchWidths),
    dataRow(["Hormone / longevity / HRT", "2,600", "<1%"], searchWidths),
    dataRow(["Medical weight loss / GLP-1", "4,900", "0%"], searchWidths),
    dataRow(["Laser / skin resurfacing", "3,300", "~2%"], searchWidths),
    dataRow(["Physician-led med spa", "620", "~18%"], searchWidths),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "The longevity and weight loss categories represent the single largest untapped demand pool in the trade area, and they are the categories where Marrow has the strongest clinical differentiation and the weakest visibility.", italics: true, size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 6: PATIENT ECONOMICS
// ============================================================
