                children: [new TextRun({ text: "◆ FULL ANALYSIS AVAILABLE IN YOUR BLUEPRINT", bold: true, color: BRAND_GOLD, size: 18, allCaps: true, characterSpacing: 30 })],
                spacing: { after: 80 }
              }),
              new Paragraph({
