children.push(h1("How to Read This Document"));

children.push(p([
  new TextRun({ text: "Every Luxora engagement begins with a Market Blueprint. It is the 30-to-60-page diagnostic that tells an owner three things with precision: where the practice actually stands against top-quartile peers, where the revenue already sitting inside the operation is leaking out, and what the sequenced path looks like to scale without replicating the leaks.", size: 22 })
