    children: [new TextRun({ text: "Market Blueprint", bold: true, color: BRAND_DARK, size: 72 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Sample Framework & Benchmark Categories", color: BRAND_GRAY, size: 28, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "", color: BRAND_GOLD })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  }),
  new Paragraph({
    children: [new TextRun({ text: "WHAT THIS DOCUMENT IS", color: BRAND_GRAY, size: 18, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "A preview of the framework, data categories,", color: BRAND_DARK, size: 22 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 40 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "and benchmarks used inside every Luxora Market Blueprint.", color: BRAND_DARK, size: 22 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Client-specific data and strategic findings are redacted.", color: BRAND_GRAY, size: 20, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "PREPARED FOR", color: BRAND_GRAY, size: 18, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Prospective Partner Review", bold: true, color: BRAND_DARK, size: 28 })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({ children: [new PageBreak()] })
);

// ============================================================
