    new TableRow({ children: [tc("RN Injector", { width: cw[0] }), tc("36", { width: cw[1] }), tc("84%", { width: cw[2] }), redactCell(cw[3], 5), tc("Near cap", { width: cw[4] })] }),
    new TableRow({ children: [tc("Laser Tech", { width: cw[0] }), tc("32", { width: cw[1] }), tc("61%", { width: cw[2] }), redactCell(cw[3], 5), tc("Underpriced", { width: cw[4] })] }),
  ]
}));

children.push(spacer(160));
children.push(p([
  new TextRun({ text: "The longevity MD has 48% of available hours unbooked. That is the single biggest asset currently under-deployed in the practice, and it is the exact provider the market is most actively searching for.", italics: true, size: 22 })
]));

children.push(h2("Front Desk and Conversion Infrastructure"));
children.push(bullet("No standardized consult script in use across providers; conversion rate varies from 34% (longevity MD) to 61% (RN injector)."));
children.push(bullet("No pre-book-out-the-door protocol at checkout; rebook rate currently 34% versus 68% peer median."));
children.push(bullet("AI follow-up sequence in GHL is active for leads but not for post-visit recapture; an entire sequence category is missing."));
children.push(bullet("No mystery-shop baseline; no score on phone answering, objection handling, or front-desk close rate."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 8 - ROADMAP
// ============================================================
children.push(h1("08  Scaling Roadmap"));

children.push(p([
  new TextRun({ text: "This roadmap is sequenced in the order the numbers support, not in the order of what is easiest to execute. Scaling to location three before the foundation is sealed would replicate the leaks, not the brand.", size: 22 })
]));

children.push(h2("Phase 1  Foundation (Months 1 through 3)"));
children.push(bullet("Install consult conversion script and same-day treatment protocol across all providers."));
children.push(bullet("Restructure membership as default onboarding pathway; enrollment at first visit, not third."));
children.push(bullet("Install pre-book-out-the-door protocol at checkout."));
children.push(bullet("Deploy post-visit AI recapture sequence in GHL."));
children.push(bullet("Baseline mystery shop at both locations; identify three highest-impact front-desk fixes."));
children.push(p([
  new TextRun({ text: "Expected output by end of Phase 1: ", bold: true, size: 22 }),
  new TextRun({ text: "blended LTV up 30-40%, membership penetration at 38-42%, consult conversion at 58-62%, monthly revenue run-rate up approximately ", size: 22 }),
  redact(8),
  new TextRun({ text: " with zero new ad spend.", size: 22 })
]));

children.push(h2("Phase 2  Demand Expansion (Months 4 through 9)"));
children.push(bullet("Launch paid search and Meta campaigns targeting the longevity and weight loss categories where the client has clinical differentiation and zero current visibility."));
children.push(bullet("Build the partnership engine: 8 to 12 strategic referral partners (high-end salons, personal trainers, women's membership clubs, boutique fitness studios) with structured co-marketing."));
children.push(bullet("Reputation engine: automate 5-star capture at point of checkout; target 40+ new reviews per month."));
children.push(bullet("Website conversion rebuild: lift form conversion from 2.1% to a target of 4.5%."));
children.push(p([
  new TextRun({ text: "Expected output by end of Phase 2: ", bold: true, size: 22 }),
  new TextRun({ text: "monthly new patients up from 93 to 135-150, longevity revenue contribution up from 23% to 35-40% of combined revenue, CAC under ", size: 22 }),
  redact(5),
  new TextRun({ text: " blended.", size: 22 })
]));

children.push(h2("Phase 3  Scale & Replication (Months 10 through 18)"));
children.push(bullet("Document the full operating system as a replicable playbook (staff training, scripts, KPIs, tech stack, compensation)."));
children.push(bullet("Model location three economics: unit revenue, startup cost, break-even timeline, required provider capacity."));
children.push(bullet("Begin site selection and buildout prep for location three; target open by month 22-24."));
children.push(bullet("Introduce management-layer hire (Director of Operations) to decouple growth from owner's day-to-day."));

children.push(h2("Phase 4  Exit Optionality (Months 18 through 36)"));
children.push(bullet("Build toward multiples-defensible financials: minimum 3-year clean P&L, audited membership MRR, documented SOPs, management team intact without owner."));
children.push(bullet("Position for strategic exit conversations: active aesthetics M&A landscape tracked, buyer set identified, comparable transaction structures modeled."));
children.push(bullet("Parallel path: hold and continue scaling to 5+ units with dividend-recap as secondary liquidity option."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 9 - FINANCIAL
// ============================================================
children.push(h1("09  Financial Projections"));

children.push(h2("12-Month Pro Forma (Conservative)"));

const fw = [3400, 2000, 2000, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: fw,
  rows: [
    headerRow(["Line Item", "Current Run-Rate", "Month 6", "Month 12"], fw),
    new TableRow({ children: [tc("Monthly Revenue", { width: fw[0] }), redactCell(fw[1], 7), redactCell(fw[2], 7), redactCell(fw[3], 7)] }),
    new TableRow({ children: [tc("Membership MRR", { width: fw[0] }), redactCell(fw[1], 7), redactCell(fw[2], 7), redactCell(fw[3], 7)] }),
    dataRow(["Longevity Contribution %", "23%", "30%", "38%"], fw),
    dataRow(["Gross Margin", "58%", "61%", "64%"], fw),
    new TableRow({ children: [tc("Paid Ad Spend", { width: fw[0] }), tc("$0", { width: fw[1] }), redactCell(fw[2], 6), redactCell(fw[3], 6)] }),
    dataRow(["Marketing % of Revenue", "0%", "5.5%", "6.4%"], fw),
    dataRow(["EBITDA Margin", "22%", "28%", "33%"], fw, [null, null, "FFF4E5", "FFF4E5"]),
  ]
}));

children.push(spacer(200));

children.push(h2("Partnership Investment Structure"));
const iw = [5400, 4000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: iw,
  rows: [
    dataRow(["Luxora 90-Day Foundation Engagement", "$9,000"], iw),
    dataRow(["Luxora Ongoing Partnership (Month 4 forward)", "$2,500 / month"], iw),
    new TableRow({ children: [tc("Projected Ad Spend (Months 4-12)", { width: iw[0] }), redactCell(iw[1], 9)] }),
    new TableRow({ children: [tc("Projected Website / Creative Rebuild", { width: iw[0] }), redactCell(iw[1], 7)] }),
    new TableRow({
      children: [
        tc("Total Year-One Growth Investment", { width: iw[0], bold: true, fill: BRAND_LIGHT, size: 22 }),
