const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, PageOrientation, LevelFormat,
  TabStopType, TabStopPosition, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageNumber, PageBreak
} = require('docx');
const fs = require('fs');

const BRAND_DARK = "1A1A1A";
const BRAND_GOLD = "B08D57";
const BRAND_LIGHT = "F5F1EA";
const BRAND_GRAY = "6B6B6B";
const REDACT_BG = "1A1A1A";
const BORDER_COLOR = "CCCCCC";

const thinBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER_COLOR };
const cellBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

function redact(length = 10) {
  return new TextRun({ text: "█".repeat(length), color: REDACT_BG, size: 22 });
}

function redactName() {
  return new TextRun({ text: "█████████████", color: REDACT_BG, size: 22 });
}

function redactNamePos() {
  return new TextRun({ text: "██████████████", color: REDACT_BG, size: 22 });
}

function p(text, opts = {}) {
  const runs = Array.isArray(text) ? text : [new TextRun({ text, ...opts.run })];
  return new Paragraph({
    children: runs,
    spacing: { after: 120, ...opts.spacing },
    alignment: opts.alignment,
    ...opts.paragraph
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 36 })],
    spacing: { before: 400, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 28 })],
    spacing: { before: 300, after: 160 }
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, color: BRAND_GOLD, size: 22, allCaps: true })],
    spacing: { before: 200, after: 100 }
  });
}

function bullet(content, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    children: typeof content === "string" ? [new TextRun({ text: content, size: 22 })] : content,
    spacing: { after: 80 }
  });
}

function tc(content, opts = {}) {
  const runs = Array.isArray(content) ? content : [new TextRun({
    text: String(content),
    bold: opts.bold,
    color: opts.color || (opts.bold ? BRAND_DARK : "333333"),
    size: opts.size || 20
  })];
  return new TableCell({
    borders: cellBorders,
    width: { size: opts.width, type: WidthType.DXA },
    shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
    margins: { top: 100, bottom: 100, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: runs, alignment: opts.alignment })]
  });
}

function headerRow(cells, widths) {
  return new TableRow({
    tableHeader: true,
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: BRAND_DARK, bold: true, color: "FFFFFF", size: 20 }))
  });
}

function dataRow(cells, widths, fills = []) {
  return new TableRow({
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: fills[i] }))
  });
}

function redactCell(width, length = 10) {
  return new TableCell({
    borders: cellBorders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill: REDACT_BG, type: ShadingType.CLEAR },
    margins: { top: 100, bottom: 100, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text: "█".repeat(length), color: REDACT_BG, size: 20 })],
      alignment: AlignmentType.CENTER
    })]
  });
}

function spacer(size = 200) {
  return new Paragraph({ children: [new TextRun({ text: "" })], spacing: { after: size } });
}

function divider() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    spacing: { before: 100, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 1 } }
  });
}

// ============================================================
const children = [];

// COVER
children.push(
  new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 2400 } }),
  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: BRAND_GOLD, size: 20, allCaps: true, characterSpacing: 40 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Market Blueprint", bold: true, color: BRAND_DARK, size: 72 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Revenue Diagnostic, Competitive Positioning, and Scaling Roadmap", color: BRAND_GRAY, size: 28, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "" })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  }),
  new Paragraph({
    children: [new TextRun({ text: "PREPARED FOR", color: BRAND_GRAY, size: 18, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [redact(22)],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [
      new TextRun({ text: "Single-Location Aesthetic Practice  |  ", color: BRAND_GRAY, size: 22 }),
      redact(16)
    ],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "CONFIDENTIAL", bold: true, color: BRAND_GOLD, size: 16, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Client name, location, and identifying revenue figures redacted.", color: BRAND_GRAY, size: 18, italics: true })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({ children: [new PageBreak()] })
);

// ============================================================
// SECTION 1 - EXECUTIVE SUMMARY
// ============================================================
children.push(h1("01  Executive Summary"));

children.push(p([
  redactName(),
  new TextRun({ text: " operates a single flagship location in a high-income suburban trade area, anchored on injectables, skin health, and laser. The practice is aesthetician-owned, with a medical director contracted for oversight and a team of one full-time NP injector plus three aestheticians. Year-to-date revenue tracks at approximately ", size: 22 }),
  redact(8),
  new TextRun({ text: ", with margins under pressure due to aggressive paid-media spend and a commission structure misaligned with retention. The brand is visible, the lead flow is strong, and the operational backbone is underbuilt.", size: 22 })
]));

children.push(p([
  new TextRun({ text: "Three structural gaps are capping revenue and margin expansion.", size: 22 })
]));

children.push(h3("The Headline Finding"));
children.push(p([
  redactName(),
  new TextRun({ text: " is leaving an estimated ", size: 22 }),
  redact(16),
  new TextRun({ text: " in annualized revenue on the table", bold: true, color: BRAND_GOLD, size: 22 }),
  new TextRun({ text: " across four recoverable categories, and an additional margin recovery opportunity sits inside the current compensation and scheduling structure. The ad spend is producing volume but not profitability, a common fingerprint for practices that scaled demand before scaling the operating system.", size: 22 })
]));

children.push(h3("Top-Line Benchmarks Versus Peer Set"));

const sumW = [2800, 2200, 2200, 2200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: sumW,
  rows: [
    headerRow(["Metric", "Client (YTD)", "Peer Median", "Top Quartile"], sumW),
    new TableRow({ children: [tc("Revenue per Provider / Mo", { width: sumW[0] }), redactCell(sumW[1], 7), tc("$58,000", { width: sumW[2], fill: "FFF4E5" }), tc("$82,000", { width: sumW[3] })] }),
    new TableRow({ children: [tc("Revenue per Treatment Room / Mo", { width: sumW[0] }), redactCell(sumW[1], 7), tc("$26,500", { width: sumW[2], fill: "FFF4E5" }), tc("$38,000", { width: sumW[3] })] }),
