  new TextRun({ text: "The 90-day engagement installs the foundation and stabilizes margin. The $2,500 monthly partnership carries the work forward: ongoing strategy, marketing oversight, monthly check-ins, accountability, and the executional discipline that separates practices that capture the upside from practices that build the plan and never run it. ", size: 22 }),
  new TextRun({ text: "Luxora is built for 12-to-24-month partnerships, not 90-day vendors.", bold: true, size: 22 })
]));

