]));

children.push(h3("4. Reposition upward on clinical authority"));
children.push(p([
  new TextRun({ text: "The dermatologist-led competitor is retaining patients at double the rate because positioning drives retention, not just acquisition. Surface the medical director, tighten clinical protocols, and reposition membership as clinical care. This is how the boutique moat gets defended against volume players.", size: 22 })
]));

children.push(spacer(300));
children.push(divider());
children.push(spacer(200));

children.push(p([
  new TextRun({ text: "Prepared by The Luxora Collective", bold: true, color: BRAND_DARK, size: 22 })
], { alignment: AlignmentType.CENTER }));
children.push(p([
  new TextRun({ text: "Premium revenue growth partner for independent med spas", color: BRAND_GRAY, size: 20, italics: true })
], { alignment: AlignmentType.CENTER }));
