const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat,
  TabStopType, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign, PageNumber, PageBreak
} = require('docx');
const fs = require('fs');

const BRAND_DARK = "1A1A1A";
const BRAND_GOLD = "B08D57";
const BRAND_LIGHT = "F5F1EA";
const BRAND_GRAY = "6B6B6B";
const REDACT_BG = "1A1A1A";
const BORDER_COLOR = "CCCCCC";

const thinBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER_COLOR };
const cellBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };

function redact(length = 10) {
  return new TextRun({ text: "█".repeat(length), color: REDACT_BG, size: 22 });
}
function redactName() {
  return new TextRun({ text: "█████████████", color: REDACT_BG, size: 22 });
}
function redactNamePos() {
  return new TextRun({ text: "██████████████", color: REDACT_BG, size: 22 });
}

function p(text, opts = {}) {
  const runs = Array.isArray(text) ? text : [new TextRun({ text, ...opts.run })];
  return new Paragraph({
    children: runs,
    spacing: { after: 120, ...opts.spacing },
    alignment: opts.alignment,
    ...opts.paragraph
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 36 })],
    spacing: { before: 400, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, color: BRAND_DARK, size: 28 })],
    spacing: { before: 300, after: 160 }
  });
}

function h3(text) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, color: BRAND_GOLD, size: 22, allCaps: true })],
    spacing: { before: 200, after: 100 }
  });
}

function bullet(content, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    children: typeof content === "string" ? [new TextRun({ text: content, size: 22 })] : content,
    spacing: { after: 80 }
  });
}

function tc(content, opts = {}) {
  const runs = Array.isArray(content) ? content : [new TextRun({
    text: String(content),
    bold: opts.bold,
    color: opts.color || (opts.bold ? BRAND_DARK : "333333"),
    size: opts.size || 20
  })];
  return new TableCell({
    borders: cellBorders,
    width: { size: opts.width, type: WidthType.DXA },
    shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
    margins: { top: 100, bottom: 100, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: runs, alignment: opts.alignment })]
  });
}

function headerRow(cells, widths) {
  return new TableRow({
    tableHeader: true,
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: BRAND_DARK, bold: true, color: "FFFFFF", size: 20 }))
  });
}

function dataRow(cells, widths, fills = []) {
  return new TableRow({
    children: cells.map((c, i) => tc(c, { width: widths[i], fill: fills[i] }))
  });
}

function redactCell(width, length = 10) {
  return new TableCell({
    borders: cellBorders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill: REDACT_BG, type: ShadingType.CLEAR },
    margins: { top: 100, bottom: 100, left: 140, right: 140 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text: "█".repeat(length), color: REDACT_BG, size: 20 })],
      alignment: AlignmentType.CENTER
    })]
  });
}

function spacer(size = 200) {
  return new Paragraph({ children: [new TextRun({ text: "" })], spacing: { after: size } });
}

function divider() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    spacing: { before: 100, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 1 } }
  });
}

// ============================================================
const children = [];

// COVER
children.push(
  new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 2400 } }),
  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: BRAND_GOLD, size: 20, allCaps: true, characterSpacing: 40 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Market Blueprint", bold: true, color: BRAND_DARK, size: 72 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Revenue Leak Audit and 90-Day Roadmap", color: BRAND_GRAY, size: 28, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "" })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_GOLD, space: 4 } }
  }),
  new Paragraph({
    children: [new TextRun({ text: "PREPARED FOR", color: BRAND_GRAY, size: 18, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [redact(22)],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [
      new TextRun({ text: "Single-Location Aesthetic Practice  |  ", color: BRAND_GRAY, size: 22 }),
      redact(16)
    ],
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "CONFIDENTIAL", bold: true, color: BRAND_GOLD, size: 16, allCaps: true, characterSpacing: 30 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Client name, location, and identifying revenue figures redacted.", color: BRAND_GRAY, size: 18, italics: true })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({ children: [new PageBreak()] })
);

// ============================================================
// SECTION 1 - EXECUTIVE SUMMARY
// ============================================================
children.push(h1("01  Executive Summary"));

children.push(p([
  redactName(),
  new TextRun({ text: " operates a single flagship location in a high-income suburban trade area, anchored on injectables, skin health, and laser. The practice is aesthetician-owned, with a contracted medical director and a team of one full-time NP injector plus three aestheticians. The brand is visible, lead flow is strong, and the operational backbone is underbuilt.", size: 22 })
]));

children.push(p([
  new TextRun({ text: "Four structural leaks are capping revenue and stalling the owner's growth goals.", size: 22 })
]));

children.push(h3("The Headline Finding"));
children.push(p([
  redactName(),
  new TextRun({ text: " is leaving an estimated ", size: 22 }),
  redact(16),
  new TextRun({ text: " in annualized revenue on the table", bold: true, color: BRAND_GOLD, size: 22 }),
  new TextRun({ text: " across four recoverable categories. Every one of these leaks is addressed inside the Luxora 90-day program through specific, installed interventions: the Membership Playbook, Package and Upsell Architecture, Sales Training Playbook, Reputation Engine, CRM and AI follow-up buildout, and Partnership Framework.", size: 22 })
]));

children.push(h3("Top-Line Benchmarks Versus Peer Set"));

const sumW = [2800, 2200, 2200, 2200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: sumW,
  rows: [
    headerRow(["Metric", "Client (YTD)", "Peer Median", "Top Quartile"], sumW),
    new TableRow({ children: [tc("Consult-to-Treatment Conversion", { width: sumW[0] }), tc("51%", { width: sumW[1] }), tc("62%", { width: sumW[2], fill: "FFF4E5" }), tc("78%", { width: sumW[3] })] }),
    new TableRow({ children: [tc("Lead-to-Booked Rate", { width: sumW[0] }), tc("21%", { width: sumW[1] }), tc("34%", { width: sumW[2], fill: "FFF4E5" }), tc("52%", { width: sumW[3] })] }),
    new TableRow({ children: [tc("Membership Penetration", { width: sumW[0] }), tc("14%", { width: sumW[1] }), tc("35%", { width: sumW[2], fill: "FFF4E5" }), tc("55%", { width: sumW[3] })] }),
    new TableRow({ children: [tc("12-Month Patient Retention", { width: sumW[0] }), tc("38%", { width: sumW[1] }), tc("56%", { width: sumW[2], fill: "FFF4E5" }), tc("72%", { width: sumW[3] })] }),
    new TableRow({ children: [tc("% Visits With Add-On", { width: sumW[0] }), tc("22%", { width: sumW[1] }), tc("42%", { width: sumW[2], fill: "FFF4E5" }), tc("67%", { width: sumW[3] })] }),
    new TableRow({ children: [tc("Avg Ticket per Visit", { width: sumW[0] }), redactCell(sumW[1], 6), tc("$520", { width: sumW[2], fill: "FFF4E5" }), tc("$780", { width: sumW[3] })] }),
  ]
}));

children.push(spacer(160));
children.push(p([
  new TextRun({ text: "Interpretation: ", bold: true, size: 22 }),
  redactName(),
  new TextRun({ text: " is running a functioning front-end but the internal conversion, retention, and upsell economics are underbuilt. Every gap above is a program deliverable inside the 90-day engagement. No tactical fix on this list requires new hires, new tech, or new services. It is all inside the existing four walls.", size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 2 - PRACTICE SNAPSHOT
// ============================================================
children.push(h1("02  Practice Snapshot"));
children.push(h2("Current-State Inputs"));

const snapW = [3200, 6200];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: snapW,
  rows: [
    dataRow(["Locations", "1 (flagship, suburban retail corridor)"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Operating Model", "Aesthetician-owned, contracted medical director, injector-forward"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Clinical Team", "1 NP injector (full-time), 3 aestheticians, 1 laser tech"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Support Team", "2 front desk, 1 part-time office manager"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Treatment Rooms", "5 (3 service rooms, 1 injection suite, 1 laser)"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Primary Tech Stack", "Boulevard (booking/EMR), AestheticsPro (POS), ActiveCampaign (email), Go High Level (lead follow-up)"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Marketing Posture", "Paid-forward (Meta 70%, Google 25%, organic 5%); aggressive promo cadence"], snapW, [BRAND_LIGHT, null]),
    new TableRow({ children: [tc("YTD Revenue", { width: snapW[0], fill: BRAND_LIGHT }), redactCell(snapW[1], 9)] }),
    dataRow(["Active Members", "62 (14% of active patient file)"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Monthly New Patients (avg)", "71"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Monthly Leads (avg)", "340"], snapW, [BRAND_LIGHT, null]),
    dataRow(["Lead-to-Booked Rate", "21%"], snapW, [BRAND_LIGHT, null]),
  ]
}));

children.push(spacer(200));

children.push(h2("Owner-Stated Goals"));
children.push(bullet("Build predictable recurring revenue outside of promotional cycles."));
children.push(bullet("Reduce owner dependency on sales; owner is currently in every high-ticket close."));
children.push(bullet("Improve retention and rebook rates; too many patients are one-and-done."));
children.push(bullet("Tighten the front-desk and consult process; too many qualified leads are leaving without booking."));
children.push(bullet("Protect the brand from local discount-driven competitors."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 3 - LOCAL MARKET & COMPETITIVE VIEW
// ============================================================
children.push(h1("03  Local Market & Competitive View"));

children.push(p([
  new TextRun({ text: "The Luxora team profiled the competitive set within the trade area, identifying the practices most likely to pull from overlapping patient demographics. Each is assessed on positioning, offer architecture, and observable promotional posture. This informs how ", size: 22 }),
  redactName(),
  new TextRun({ text: " differentiates inside the Partnership Framework and the Reputation Engine buildout.", size: 22 })
]));

children.push(h2("Direct Competitor Set"));

const compW = [2100, 2100, 2600, 2600];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: compW,
  rows: [
    headerRow(["Competitor", "Positioning", "Promotional Posture", "Signature Offer"], compW),
    new TableRow({ children: [redactCell(compW[0], 8), tc("National chain", { width: compW[1] }), tc("Aggressive, constant promos", { width: compW[2] }), tc("$9/unit Botox, BOGO filler", { width: compW[3] })] }),
    new TableRow({ children: [redactCell(compW[0], 8), tc("Dermatologist-led", { width: compW[1] }), tc("Restrained, authority-driven", { width: compW[2] }), tc("Physician consult packages", { width: compW[3] })] }),
    new TableRow({ children: [redactCell(compW[0], 8), tc("Boutique spa", { width: compW[1] }), tc("Membership-led", { width: compW[2] }), tc("Monthly skincare membership", { width: compW[3] })] }),
    new TableRow({ children: [redactCell(compW[0], 8), tc("Newer entrant", { width: compW[1] }), tc("Loss-leader acquisition", { width: compW[2] }), tc("First-visit $99 Botox", { width: compW[3] })] }),
    new TableRow({ children: [tc([redactName()], { width: compW[0], bold: true, fill: BRAND_LIGHT }), tc("Aesthetician-owned, injector-forward", { width: compW[1], fill: BRAND_LIGHT }), tc("Rotating monthly promos", { width: compW[2], fill: BRAND_LIGHT }), tc("Mixed discount offers", { width: compW[3], fill: BRAND_LIGHT })] }),
  ]
}));

children.push(spacer(200));

children.push(h2("Positioning Implication"));
children.push(p([
  new TextRun({ text: "Competing on promo cadence keeps ", size: 22 }),
  redactName(),
  new TextRun({ text: " in the same mental category as the national chain and the newer entrant. The 90-day program resets this through three specific moves: repositioning membership as a clinical care plan (Membership Playbook), installing a Partnership Framework that generates high-trust referrals outside of paid channels, and activating the Reputation Engine to amplify five-star outcomes so the brand story is carried by patients, not promos.", size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ============================================================
// SECTION 4 - REVENUE LEAK AUDIT
// ============================================================
children.push(h1("04  Revenue Leak Audit"));
children.push(p([
  new TextRun({ text: "This section quantifies the revenue already inside the operation that is not being captured. Each leak is calculated conservatively using ", size: 22 }),
  redactNamePos(),
  new TextRun({ text: " own 12-month data, with peer-median and top-quartile benchmarks for reference. Every leak below is addressed inside the 90-day program through a specific playbook.", size: 22 })
]));

children.push(h2("Leak #1  Lead-to-Booked Conversion"));

const lw = [3200, 2100, 2100, 2000];
children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: lw,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], lw),
    dataRow(["Lead-to-Booked Rate", "21%", "34%", "52%"], lw),
    dataRow(["Monthly Leads", "340", "—", "—"], lw),
    dataRow(["Leads That Do Not Book", "268", "—", "—"], lw),
    dataRow(["Speed-to-First-Contact", "11 hours", "Under 10 min", "Under 5 min"], lw),
    new TableRow({ children: [tc("Monthly Revenue Forfeited", { width: lw[0] }), redactCell(lw[1], 7), tc("—", { width: lw[2], fill: "FFF4E5" }), tc("—", { width: lw[3] })] }),
    new TableRow({ children: [tc("Annualized Revenue Forfeited", { width: lw[0], fill: BRAND_LIGHT, bold: true }), redactCell(lw[1], 8), tc("—", { width: lw[2] }), tc("—", { width: lw[3] })] }),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "Root cause: ", bold: true, size: 22 }),
  new TextRun({ text: "Speed-to-lead is the primary driver; 72% of non-converting leads cite no callback. The GHL follow-up sequence is active but not tuned for speed or SMS-first cadence.", size: 22 })
]));
children.push(p([
  new TextRun({ text: "Fixed inside the 90-day program by: ", bold: true, color: BRAND_GOLD, size: 22 }),
  new TextRun({ text: "CRM and AI Follow-Up Buildout (rebuilt GHL sequences, SMS-first speed-to-lead, missed-call text-back, post-lead nurture), plus Front Desk Script Install and Sales Training Playbook.", size: 22 })
]));

children.push(h2("Leak #2  Membership Penetration"));

children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: lw,
  rows: [
    headerRow(["Indicator", "Current", "Peer Median", "Top Quartile"], lw),
    dataRow(["Active Members", "62", "—", "—"], lw),
    dataRow(["Active Patient File", "442", "—", "—"], lw),
    dataRow(["Membership Penetration", "14%", "35%", "55%"], lw),
    dataRow(["Avg MRR per Member", "$109", "$135", "$185"], lw),
    new TableRow({ children: [tc("Monthly MRR Forfeited", { width: lw[0] }), redactCell(lw[1], 7), tc("—", { width: lw[2], fill: "FFF4E5" }), tc("—", { width: lw[3] })] }),
    new TableRow({ children: [tc("Annualized MRR Forfeited", { width: lw[0], fill: BRAND_LIGHT, bold: true }), redactCell(lw[1], 8), tc("—", { width: lw[2] }), tc("—", { width: lw[3] })] }),
  ]
}));

children.push(spacer(120));
children.push(p([
  new TextRun({ text: "Root cause: ", bold: true, size: 22 }),
  new TextRun({ text: "Membership is priced and pitched as a discount stack, which makes it easy to cancel and easy for discount-shoppers to avoid. It is not positioned as the default onboarding pathway for new patients.", size: 22 })
]));
children.push(p([
  new TextRun({ text: "Fixed inside the 90-day program by: ", bold: true, color: BRAND_GOLD, size: 22 }),
  new TextRun({ text: "Membership Playbook (repositioning, tier restructure, clinical-care-plan framing, enrollment-at-first-visit protocol, staff talk tracks).", size: 22 })
]));

children.push(new Paragraph({ children: [new PageBreak()] }));

children.push(h2("Leak #3  Retention and Rebook Cadence"));

children.push(new Table({
  width: { size: 9400, type: WidthType.DXA },
  columnWidths: lw,
  rows: [
